ASSET_LOGOS = LOGO_MAP

def get_asset_logo(symbol):
    clean = str(symbol).upper().strip()
    if clean in LOGO_MAP:
        return LOGO_MAP[clean]
    base = clean.split('-')[0].replace('^', '')
    if base in LOGO_MAP:
        return LOGO_MAP[base]
    if clean.startswith(('USTB', 'UST', 'US10')):
        return "/static/logos/us_treasury.svg"
    if clean.startswith(('UKTB', 'UKG', 'UK10')):
        return "/static/logos/uk_dmo.svg"
    if clean.startswith(('JPTB', 'JGB', 'JP10')):
        return "/static/logos/mof_japan.svg"
    if clean.startswith(('T9', 'T1', 'T3', 'FXD', 'IFB', 'KE91', 'BOND')):
        return "/static/logos/cbk.svg"
    return "/static/logos/nse.svg"

