def get_company_image(symbol):
    clean = str(symbol).upper().strip()
    if clean in COMPANY_IMAGES:
        return COMPANY_IMAGES[clean]
    base = clean.split('-')[0].replace('^', '')
    if base in COMPANY_IMAGES:
        return COMPANY_IMAGES[base]
    if clean.startswith(('USTB', 'UST', 'US10')):
        return "/static/companies/us_treasury.jpg"
    if clean.startswith(('UKTB', 'UKG', 'UK10')):
        return "/static/companies/uk_dmo.jpg"
    if clean.startswith(('JPTB', 'JGB', 'JP10')):
        return "/static/companies/mof_japan.jpg"
    if clean.startswith(('T9', 'T1', 'T3', 'FXD', 'IFB', 'KE91', 'BOND')):
        return "/static/companies/cbk.jpg"
    return "/static/companies/nse.jpg"

