# Sovereign Bonds & Treasury Bills Catalog
BONDS_CATALOG = {sym: d for sym, d in ASSETS.items() if d.get("category") == "bonds"}

# Institutional Physical & Futures Commodities Catalog
COMMODITIES_CATALOG = {sym: d for sym, d in ASSETS.items() if d.get("category") == "commodities"}

def get_bonds_data():
    """
    Returns comprehensive fixed-income desk data for the bonds & treasury bills page,
    including the full catalog, yield curve, auction calendar, and portfolio analytics.
    """
    bonds = list(BONDS_CATALOG.values())
    tbills = [b for b in bonds if b.get("subcategory") == "tbill"]
    govt_bonds = [b for b in bonds if b.get("subcategory") != "tbill"]

    # Yield ladder for display
    yield_ladder = []
    for b in sorted(bonds, key=lambda x: x.get("maturity_days", 0)):
        yield_ladder.append({
            "symbol": b["symbol"],
            "name": b["name"],
            "country": b.get("country", "Kenya"),
            "currency": b.get("currency", "KES"),
            "tenor": f"{b.get('maturity_days', 90)}D" if b.get("subcategory") == "tbill" else f"{b.get('maturity_days', 3650)//365}Y",
            "yield": b.get("yield_to_maturity", b.get("weighted_avg_yield", 0.0)),
            "coupon": b.get("coupon_rate", 0.0),
            "price": b.get("price", 100.0),
            "change": b.get("change", 0.0),
            "maturity_date": b.get("maturity_date", "N/A"),
            "tax_exempt": b.get("tax_exempt", False),
        })

    return {
        "all_bonds": bonds,
        "tbills": tbills,
        "govt_bonds": govt_bonds,
        "yield_ladder": yield_ladder,
        "auction_calendar": CBK_AUCTION_CALENDAR,
        "recent_auctions": CBK_RECENT_AUCTIONS,
        "bond_portfolio": BOND_PORTFOLIO,
        "yield_curves": SOVEREIGN_YIELD_CURVES,
    }

